function NotifyNetWorkManager.SendWorldChatData(words, chatType, callback)
    local msg = {};
    msg = NotifyNetWorkManager.InitChatMsg(words, 1);
    msg["chatTab"] = "world";
    msg["chatType"] = chatType;
    if(chatType == "redBag" or chatType == "extend_challage") then
        NetworkManager.SendRequestToNotifyServer("chat.chatHandler.worldSend", msg, callback);
    elseif(chatType == "extend_dice" or chatType == "word") then
        NetworkManager.SendRequestToNotifyServer("chat.chatHandler.worldSend", msg, callback);
    end
end

function NotifyNetWorkManager.InitChatMsg(word, channel)
    local msg = {};
    msg["chatChannel"] = channel;
    msg["words"] = word;
    local x, y = string.find(word, ChatDialogModel.toolPrefix .. "challenge")
    if(x ~= nil and y ~= nil) then
        msg["challenge"] = 1;
    end
    msg["uid"] = Player.uid;
    msg["nick"] = Player.nick;
    msg["headIconId"] = Player.headIcon;
    msg["vip"] = Player.vip;
    msg["clientTime"] = os.time();
    msg["chatBubbleID"] = ChatDialogModel.currentBubbleId;
    msg["frameID"] = Player.frameId;
    return msg;
end

