function NotifyNetWorkManager.SendChatTopData(word, channel, callback)
    local chatChannel = 1
    if channel == "world" then
        chatChannel = 1
    elseif channel == "realm" then
        chatChannel = 2
    elseif channel == "family" then
        chatChannel = 3
    end
    local msg = {}
    msg = NotifyNetWorkManager.InitChatMsg(word, chatChannel)
    msg["chatTab"] = channel;
    msg["istop"] = 1
    NetworkManager.SendRequestToNotifyServer("chat.chatHandler.chatTopSend", msg, callback);
end

