function NotifyNetWorkManager.SendRedBagData(id, chatTab, word, callback)
    local msg = {};
    local tmpChatType = 1;
    if(chatTab == "world") then
        tmpChatType = 1;
    elseif(chatTab == "realm") then
        tmpChatType = 2;
    elseif(chatTab == "family") then
        tmpChatType = 3;
    end
    msg = NotifyNetWorkManager.InitChatMsg(word,tmpChatType);
    msg["chatTab"] = chatTab;
    msg["redBagId"] = id;
    NetworkManager.SendRequestToNotifyServer("chat.chatHandler.redbagSend", msg, callback);
end

